def split_csv(line):
    fields = []
    field = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(c)
        elif c == '"' and not field:
            in_quotes = True
        elif c == ',':
            fields.append(''.join(field))
            field = []
        else:
            field.append(c)
        i += 1

    fields.append(''.join(field))
    return fields
